const listInboxConversationIDs = `-- name: ListInboxConversationIDs :many
SELECT c.id, c.last_message_at
FROM conversation c
JOIN course_member o ON o.id = c.opener_member_id
JOIN actor oa ON oa.id = o.actor_id AND oa.status = 'active'
LEFT JOIN course_member op ON op.id = o.principal_member_id
JOIN LATERAL (
    SELECT m.id FROM conversation_message m
    WHERE m.conversation_id = c.id AND m.author_member_id = c.opener_member_id
    ORDER BY m.seq DESC LIMIT 1) latest ON true
WHERE c.respondent_member_id = $1 AND c.status = 'open'
  AND c.last_author_member_id = c.opener_member_id
  AND o.status = 'active' AND (o.expires_at IS NULL OR o.expires_at > $2)
  AND (o.principal_member_id IS NULL
       OR (op.status = 'active' AND (op.expires_at IS NULL OR op.expires_at > $2)))
  AND NOT EXISTS (SELECT 1 FROM conversation_message_retraction x WHERE x.message_id = latest.id)
  AND NOT EXISTS (SELECT 1 FROM action a
                   WHERE a.target_type = 'conversation' AND a.target_id = c.id AND a.action_type = 'conversation.answer'
                     AND a.status = 'proposed' AND a.member_id = $1
                     AND a.payload->>'in_reply_to_message_id' = latest.id::text)
  AND ($3::timestamptz IS NULL
       OR (c.last_message_at, c.id) > ($3::timestamptz, $4::uuid))
ORDER BY c.last_message_at, c.id
LIMIT $5
`

type ListInboxConversationIDsParams struct {
	MemberID uuid.UUID
	Now      *time.Time
	AfterAt  *time.Time
	AfterID  *uuid.UUID
	MaxRows  int32
}

type ListInboxConversationIDsRow struct {
	ID            uuid.UUID
	LastMessageAt *time.Time
}

// Open conversations addressed to a seat in which the opener spoke last,
// the opener's newest message is not retracted, and no answer of the seat's
// to that message waits for a decision, the longest waiting first, after a
// (last_message_at, id) cursor. The opener's seat, its actor and, for a
// delegate, its principal's seat must be live: whatever cannot count again
// by itself is left out here, so that it does not stand for good in front
// of what can be answered. Whether each opener may still address the seat
// is for the caller to say, in Go.
func (q *Queries) ListInboxConversationIDs(ctx context.Context, arg ListInboxConversationIDsParams) ([]ListInboxConversationIDsRow, error) {
	rows, err := q.db.Query(ctx, listInboxConversationIDs,
		arg.MemberID,
		arg.Now,
		arg.AfterAt,
		arg.AfterID,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListInboxConversationIDsRow
	for rows.Next() {
		var i ListInboxConversationIDsRow
		if err := rows.Scan(&i.ID, &i.LastMessageAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listMessageSources = `-- name: ListMessageSources :many
SELECT s.message_id, s.position, s.document_id, s.version_id, s.file_id, s.page, s.slide, s.part,
       d.kind AS document_kind, d.title AS document_title, d.purged_at AS document_purged_at,
       v.seq AS version_seq, v.purged_at AS version_purged_at, f.filename
FROM conversation_message_source s
JOIN document d ON d.id = s.document_id
JOIN document_version v ON v.id = s.version_id
LEFT JOIN document_version_file f ON f.id = s.file_id
WHERE s.message_id = ANY($1::uuid[])
ORDER BY s.message_id, s.position
`

type ListMessageSourcesRow struct {
	MessageID        uuid.UUID
	Position         int32
	DocumentID       uuid.UUID
	VersionID        uuid.UUID
	FileID           *uuid.UUID
	Page             *int32
	Slide            *int32
	Part             *int32
	DocumentKind     string
	DocumentTitle    string
	DocumentPurgedAt *time.Time
	VersionSeq       int32
	VersionPurgedAt  *time.Time
	Filename         *string
}

// The sources of the given messages, each message's in order, with what
// an export and every reader are told of them alike: the document's kind
// and title as they are now, the version's seq, whether either was purged,
// and the file's name while it has one. Whom each may be shown to, and
// how much, is the caller's to decide, reader by reader, in Go
// (tools.sourceReader), with document.get's rules.
func (q *Queries) ListMessageSources(ctx context.Context, messageIds []uuid.UUID) ([]ListMessageSourcesRow, error) {
	rows, err := q.db.Query(ctx, listMessageSources, messageIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListMessageSourcesRow
	for rows.Next() {
		var i ListMessageSourcesRow
		if err := rows.Scan(
			&i.MessageID,
			&i.Position,
			&i.DocumentID,
			&i.VersionID,
			&i.FileID,
			&i.Page,
			&i.Slide,
			&i.Part,
			&i.DocumentKind,
			&i.DocumentTitle,
			&i.DocumentPurgedAt,
			&i.VersionSeq,
			&i.VersionPurgedAt,
			&i.Filename,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listMyConversations = `-- name: ListMyConversations :many
SELECT c.id, c.opener_member_id, coalesce(c.last_message_at, c.created_at)::timestamptz AS last_activity_at
FROM conversation c
WHERE c.opener_member_id = ANY($1::uuid[])
  AND ($2::timestamptz IS NULL
       OR (coalesce(c.last_message_at, c.created_at), c.id) < ($2::timestamptz, $3::uuid))
ORDER BY coalesce(c.last_message_at, c.created_at) DESC, c.id DESC
LIMIT $4
`

type ListMyConversationsParams struct {
	MemberIds []uuid.UUID
	AfterAt   *time.Time
	AfterID   *uuid.UUID
	MaxRows   int32
}

type ListMyConversationsRow struct {
	ID             uuid.UUID
	OpenerMemberID uuid.UUID
	LastActivityAt time.Time
}

// The conversations the given seats opened, newest activity first — its
// last message, or its opening while it has none — after a
// (last_activity_at, id) cursor, both descending. The seats are the
// caller's own that count now, which me.conversations works out before
// this, as authorization would: nothing here reads anyone else's.
func (q *Queries) ListMyConversations(ctx context.Context, arg ListMyConversationsParams) ([]ListMyConversationsRow, error) {
	rows, err := q.db.Query(ctx, listMyConversations,
		arg.MemberIds,
		arg.AfterAt,
		arg.AfterID,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListMyConversationsRow
	for rows.Next() {
		var i ListMyConversationsRow
		if err := rows.Scan(&i.ID, &i.OpenerMemberID, &i.LastActivityAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listRespondentCandidates = `-- name: ListRespondentCandidates :many
SELECT m.id, a.display_name, a.kind, coalesce(a.hosting, '')::text AS hosting, m.role, m.principal_member_id,
       m.answers_course, own.display_name AS owner_name, seen.last_used_at AS last_seen_at
FROM course_member m
JOIN actor a ON a.id = m.actor_id
LEFT JOIN actor own ON own.id = a.owner_actor_id
LEFT JOIN course_member p ON p.id = m.principal_member_id
LEFT JOIN LATERAL (
    SELECT cr.last_used_at FROM credential cr
    WHERE a.kind = 'agent' AND cr.actor_id = a.id AND cr.kind = 'api_token' AND cr.revoked_at IS NULL
      AND cr.last_used_at IS NOT NULL AND (cr.expires_at IS NULL OR cr.expires_at > $2)
    ORDER BY cr.last_used_at DESC LIMIT 1) seen ON true
WHERE m.course_id = $1 AND m.id <> $3
  AND m.status = 'active' AND (m.expires_at IS NULL OR m.expires_at > $2)
  AND m.perm_conversation_answer <> 'denied' AND a.status = 'active'
  AND (m.principal_member_id IS NULL OR m.principal_member_id = $3
       OR (m.answers_course AND p.perm_member_manage <> 'denied'))
  AND a.kind = 'agent' AND a.hosting = 'runtime'
  AND (a.owner_actor_id IS NULL OR EXISTS (SELECT 1 FROM actor o WHERE o.id = a.owner_actor_id AND o.status = 'active'))
  AND EXISTS (SELECT 1 FROM credential rt
               WHERE rt.actor_id = a.id AND rt.issued_to_service = 'agent_runtime' AND rt.revoked_at IS NULL
                 AND (rt.expires_at IS NULL OR rt.expires_at > $2))
ORDER BY m.id
LIMIT $4
`

type ListRespondentCandidatesParams struct {
	CourseID       uuid.UUID
	Now            *time.Time
	CallerMemberID uuid.UUID
	MaxRows        int32
}

type ListRespondentCandidatesRow struct {
	ID                uuid.UUID
	DisplayName       string
	Kind              string
	Hosting           string
	Role              string
	PrincipalMemberID *uuid.UUID
	AnswersCourse     bool
	OwnerName         *string
	LastSeenAt        *time.Time
}

// The seats that might answer a caller: agents' seats, live, held by an
// active actor, with conversation_answer not denied on the row, and, for a
// delegate, either the caller's own or one that answers the course, whose
// principal's row holds member_manage. Never a person's: conversations are
// with agents. An agent's seat only while people in the site may ask it
// (docs/schema.md §2.8), by the rule of SiteChatOf, its status asked above:
// a runtime agent while the site's runtime holds a live token for it, and
// never an mcp agent, which its owner's own tools reach elsewhere. kind and
// hosting are read to leave out, never to let in. Which of them the caller may
// address is decided in Go (tools.addressing), which this only narrows to
// what it could accept: every student's own agent answers, and only its
// principal. Unpaged: what is left is a course's agents, and the caller's
// own agents, a handful; max_rows bounds them anyway.
func (q *Queries) ListRespondentCandidates(ctx context.Context, arg ListRespondentCandidatesParams) ([]ListRespondentCandidatesRow, error) {
	rows, err := q.db.Query(ctx, listRespondentCandidates,
		arg.CourseID,
		arg.Now,
		arg.CallerMemberID,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRespondentCandidatesRow
	for rows.Next() {
		var i ListRespondentCandidatesRow
		if err := rows.Scan(
			&i.ID,
			&i.DisplayName,
			&i.Kind,
			&i.Hosting,
			&i.Role,
			&i.PrincipalMemberID,
			&i.AnswersCourse,
			&i.OwnerName,
			&i.LastSeenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

